import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import moment from "moment";
import { get_current_details } from "@/mixins/GetCuurentUser.js";
import { daily_leave_reports } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar
  },
  mixins: [get_current_details],
  data() {
    return {
      SnackBarComponent: {},
      searchQuery: "",
      sortBy: [{
        key: "user_name",
        order: "asc"
      }],
      goLoading: false,
      selectedDate: "",
      minmonth: "",
      leaveSub: "Leave",
      subleaveitemsall: ["Leave", "Comp Off", "Week Off"],
      subleaveitemscomp: ["Leave", "Comp Off"],
      subleaveitemsweek: ["Leave", "Week Off"],
      headers: [{
        title: "Member Name",
        value: "user_name",
        sortable: true,
        align: "start"
      }, {
        title: "Email ID",
        value: "user_email_id",
        sortable: true,
        align: "start"
      }, {
        title: "Leave Type",
        value: "leave_type",
        sortable: true,
        align: "start"
      }],
      height: 0,
      fixed: true,
      endmodal: false,
      tableData: [],
      tableLoading: false,
      computedDateFormatted: this.formatDate(new Date()),
      datePicker: false,
      tempDate: null,
      date: null,
      itemsPerPage: 10,
      currentPage: 1,
      pageCount: 0,
      startItem: 0,
      endItem: 0,
      totalCount: 0,
      next_token: null,
      windowHeight: 0,
      showFilterDrawer: false
    };
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 250;
    this.selectedDate = this.get_orgdate(this.$store.getters.GetUserObj.organization.organization_created_on);
    this.minmonth = moment(this.selectedDate, "MM/DD/YYYY").format("YYYY-MM-DD");
    this.tableLoading = true;
    await this.get_current_details();
    await this.absent_reportss();
  },
  async created() {},
  watch: {
    currentPage() {
      this.get_data();
    }
  },
  computed: {
    computedDateDisplay() {
      return this.displayFormatDate(this.computedDateFormatted);
    },
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(item => item.user_name && item.user_name.toLowerCase().includes(searchTerm) || item.user_email_id && item.user_email_id.toLowerCase().includes(searchTerm) || item.leave_type && item.leave_type.toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });
      return sortedItems;
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    activeFiltersCount() {
      let count = 0;

      // Count date filter (if not default)
      if (this.computedDateFormatted && this.computedDateFormatted !== this.formatDate(new Date())) {
        count++;
      }

      // Count leave type filter (if not default)
      if (this.leaveSub && this.leaveSub !== "Leave") {
        count++;
      }
      return count;
    }
  },
  methods: {
    back_action() {
      this.$store.commit("SetattendenceBack", true);
      this.$router.push("/home/UserLevel");
    },
    displayFormatDate(date) {
      if (!date) return "";
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    saveDate() {
      this.date = this.tempDate;
      this.computedDateFormatted = this.tempDate ? this.formatDate(this.tempDate) : "";
      this.datePicker = false;
      this.tableData = [];
      const org = this.$store.getters.GetUserObj.organization;
      if (org.week_off_settings === false && org.comp_off === false) {
        this.get_data();
      }
    },
    get_orgdate(date) {
      let a = new Date(date * 1000).toLocaleTimeString("en-US", {
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      });
      return a.toUpperCase();
    },
    get_data() {
      this.next_token = null;
      this.tableData = [];
      this.goLoading = true;
      this.currentPage = 1;
      this.absent_reportss();
    },
    get_datanewfilter() {
      if (this.currentObject.week_off_settings == false && this.currentObject.comp_off == false) {
        this.next_token = null;
        this.tableData = [];
        this.currentPage = 1;
        this.absent_reportss();
      }
    },
    dateformating(CurrentDate) {
      if (!CurrentDate) return null;
      const [year, month, day] = CurrentDate.split("-");
      return `${day}/${month}/${year}`;
    },
    gettimecal() {
      this.endmodal = true;
    },
    async absent_reportss() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(daily_leave_reports, {
          input: {
            organization_id: data.organization.organization_id,
            swipe_date: this.computedDateFormatted,
            limit: this.itemsPerPage,
            nextToken: this.next_token,
            action_type: this.leaveSub == "Leave" ? undefined : this.leaveSub == "Comp Off" ? "CUMPOFF" : "WEEKOFF"
          }
        }));
        this.tableLoading = false;
        var response = result.data.daily_leave_reports;
        this.next_token = response.nextToken;
        this.goLoading = false;
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
          this.totalCount = response.totalCount || this.tableData.length;
          this.pageCount = Math.ceil(this.totalCount / this.itemsPerPage);
        } else {
          this.goLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.goLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    updatePageItems(newPage) {
      this.currentPage = newPage;
      this.absent_reportss();
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.updatePageItems(this.currentPage);
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "user_name" || key === "user_email_id" || key === "leave_type") {
        return value.toLowerCase();
      }
      return value;
    },
    getLeaveTypeColor(leaveType) {
      const colors = {
        LEAVE: "#FF9800",
        CUMPOFF: "#4CAF50",
        WEEKOFF: "#2196F3"
      };
      return colors[leaveType] || "#757575";
    },
    getLeaveTypeIcon(leaveType) {
      const icons = {
        LEAVE: "mdi-calendar-remove",
        CUMPOFF: "mdi-calendar-check",
        WEEKOFF: "mdi-calendar-weekend"
      };
      return icons[leaveType] || "mdi-calendar-question";
    },
    getLeaveTypeDisplayName(leaveType) {
      const names = {
        LEAVE: "Leave",
        CUMPOFF: "Comp Off",
        WEEKOFF: "Week Off"
      };
      return names[leaveType] || leaveType || "N/A";
    },
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    clear_data() {
      this.leaveSub = "Leave";
      this.computedDateFormatted = this.formatDate(new Date());
      this.get_data();
    },
    applyFilterFromDrawer() {
      this.get_data();
      this.showFilterDrawer = false;
    }
  }
};
